"""A strategy's webhook secret is issued once and regenerated by its author
(multi-user design AD6, AD8; tasks.md D.3).

``POST /api/strategies`` answers the plain secret once and stores only its SHA-256.
``POST /api/strategies/{id}/webhook-secret`` replaces the hash and answers the new
secret once; the old secret stops opening the webhook at the commit. Another user's
strategy answers 404, the same as a strategy that does not exist, and an archived
strategy answers 409.

Runs on a database migrated to ``head`` with Alembic and through the whole
application, so a regenerated secret is tried at the real ``/webhook/tradingview``.
"""

import asyncio
import logging
from collections.abc import AsyncIterator, Iterator
from typing import Any
from uuid import UUID, uuid4

import pytest
from httpx import ASGITransport, AsyncClient, Response
from sqlalchemy import text
from sqlalchemy.ext.asyncio import (
    AsyncEngine,
    AsyncSession,
    async_sessionmaker,
    create_async_engine,
)

from strategy_manager.main import create_app
from strategy_manager.shared import db as shared_db
from strategy_manager.strategies.infrastructure.pair_catalog_router import get_pair_catalog
from tests.identity_auth import ADMIN_HEADERS, OTHER_HEADERS, seed_admin, sign_in_as_admin
from tests.owner import OWNER_ID, secret_hash, seed_owner
from tests.pg_head_schema import migrated_head_database

pytestmark = pytest.mark.integration

ALLOWED_IP = "52.89.214.238"
OLD_SECRET = "the-secret-issued-at-creation-4b7e"
UNAUTHORIZED = {"detail": "unauthorized"}


