async def _seed(
    engine: AsyncEngine, *, author: UUID, secret: str = OLD_SECRET, archived: bool = False
) -> UUID:
    strategy_id = uuid4()
    async with engine.begin() as conn:
        await conn.execute(
            text(
                "INSERT INTO strategies (id, name, exchange, venue, settlement_currency, "
                "enabled, fill_mode, allowed_pairs, author_id, webhook_secret_hash, "
                "archived_at) VALUES (:id, :name, 'bybit', 'usdt-m', 'USDT', false, "
                "'PARTIAL', ARRAY['STXUSDT'], :author, :hash, "
                "CASE WHEN :archived THEN now() END)"
            ),
            {
                "id": strategy_id,
                "name": f"strategy-{strategy_id}",
                "author": author,
                "hash": secret_hash(secret),
                "archived": archived,
            },
        )
    return strategy_id


async def _stored_hash(engine: AsyncEngine, strategy_id: UUID) -> str:
    async with engine.connect() as conn:
        return str(
            (
                await conn.execute(
                    text("SELECT webhook_secret_hash FROM strategies WHERE id = :id"),
                    {"id": strategy_id},
                )
            ).scalar_one()
        )


async def _regenerate(
    client: AsyncClient, strategy_id: UUID, headers: dict[str, str] = ADMIN_HEADERS
) -> Response:
    return await client.post(f"/api/strategies/{strategy_id}/webhook-secret", headers=headers)


async def _webhook(client: AsyncClient, strategy_id: UUID, secret: str) -> Response:
    return await client.post(
        "/webhook/tradingview", params={"secret": secret}, json=_payload(strategy_id)
    )


def _create_body(strategy_id: UUID) -> dict[str, Any]:
    return {
        "id": str(strategy_id),
        "name": f"created-{strategy_id}",
        "exchange": "bybit",
        "venue": "usdt-m",
        "settlement_currency": "USDT",
        "fill_mode": "PARTIAL",
        "allowed_pairs": ["STXUSDT"],
    }


# ---------------------------------------------------------------------------
# Creating: the secret is shown once, and only its hash is stored
# ---------------------------------------------------------------------------


async def test_creating_answers_the_secret_once_and_stores_only_its_hash(
    client: AsyncClient, engine: AsyncEngine
) -> None:
    strategy_id = uuid4()

    created = await client.post(
        "/api/strategies", json=_create_body(strategy_id), headers=ADMIN_HEADERS
    )

    assert created.status_code == 201, created.text
    secret = created.json()["webhook_secret"]
    assert len(secret) >= 43
    assert created.headers["cache-control"] == "no-store"
    stored = await _stored_hash(engine, strategy_id)
    assert stored == secret_hash(secret)
    assert secret != stored


async def test_no_read_of_the_strategy_returns_the_secret_or_the_hash(
    client: AsyncClient, engine: AsyncEngine
) -> None:
    strategy_id = uuid4()
    created = await client.post(
        "/api/strategies", json=_create_body(strategy_id), headers=ADMIN_HEADERS
    )
    secret = created.json()["webhook_secret"]
    stored = await _stored_hash(engine, strategy_id)

    reads = [
        await client.get(f"/api/strategies/{strategy_id}", headers=ADMIN_HEADERS),
        await client.get("/api/strategies", headers=ADMIN_HEADERS),
        await client.get(f"/api/strategies/{strategy_id}/events", headers=ADMIN_HEADERS),
    ]

    for read in reads:
        assert read.status_code == 200
        assert secret not in read.text
        assert stored not in read.text
        assert "webhook_secret" not in read.text


async def test_the_secret_issued_at_creation_opens_the_webhook(
    client: AsyncClient, engine: AsyncEngine
) -> None:
    strategy_id = uuid4()
    created = await client.post(
        "/api/strategies", json=_create_body(strategy_id), headers=ADMIN_HEADERS
    )
    secret = created.json()["webhook_secret"]

    wrong = await _webhook(client, strategy_id, "not-the-secret")
    right = await _webhook(client, strategy_id, secret)

    assert (wrong.status_code, wrong.json()) == (401, UNAUTHORIZED)
    assert right.status_code == 200


# ---------------------------------------------------------------------------
# Regenerating
# ---------------------------------------------------------------------------


async def test_regenerating_answers_a_new_secret_once_and_replaces_the_hash(
    client: AsyncClient, engine: AsyncEngine, admin_id: UUID
) -> None:
    strategy_id = await _seed(engine, author=admin_id)

    response = await _regenerate(client, strategy_id)

    assert response.status_code == 200
    assert response.headers["cache-control"] == "no-store"
    assert set(response.json()) == {"webhook_secret"}
    secret = response.json()["webhook_secret"]
    assert secret != OLD_SECRET
    assert await _stored_hash(engine, strategy_id) == secret_hash(secret)


async def test_the_old_secret_is_refused_at_the_webhook_and_the_new_one_opens_it(
    client: AsyncClient, engine: AsyncEngine, admin_id: UUID
) -> None:
    strategy_id = await _seed(engine, author=admin_id)
    before = await _webhook(client, strategy_id, OLD_SECRET)
    assert before.status_code == 200

    secret = (await _regenerate(client, strategy_id)).json()["webhook_secret"]

    old = await _webhook(client, strategy_id, OLD_SECRET)
    new = await _webhook(client, strategy_id, secret)
    assert (old.status_code, old.json()) == (401, UNAUTHORIZED)
    assert new.status_code == 200


async def test_regenerating_twice_invalidates_the_first_new_secret(
    client: AsyncClient, engine: AsyncEngine, admin_id: UUID
) -> None:
    strategy_id = await _seed(engine, author=admin_id)

    first = (await _regenerate(client, strategy_id)).json()["webhook_secret"]
    second = (await _regenerate(client, strategy_id)).json()["webhook_secret"]

    assert first != second
    assert (await _webhook(client, strategy_id, first)).status_code == 401
    assert (await _webhook(client, strategy_id, second)).status_code == 200


async def test_another_authors_strategy_answers_404_like_a_missing_one(
    client: AsyncClient, engine: AsyncEngine
) -> None:
    """AD8: the answer cannot tell somebody else's strategy from none at all, and
    the other author's secret is untouched."""
    theirs = await _seed(engine, author=OWNER_ID)
    missing = uuid4()

    refused = await _regenerate(client, theirs)
    absent = await _regenerate(client, missing)

    assert (refused.status_code, absent.status_code) == (404, 404)
    assert refused.json() == {"detail": f"no strategy registered under id {theirs}"}
    assert absent.json() == {"detail": f"no strategy registered under id {missing}"}
    assert await _stored_hash(engine, theirs) == secret_hash(OLD_SECRET)
    assert (await _webhook(client, theirs, OLD_SECRET)).status_code == 200


async def test_an_archived_strategy_is_refused_with_409_and_keeps_its_secret(
    client: AsyncClient, engine: AsyncEngine, admin_id: UUID
) -> None:
    strategy_id = await _seed(engine, author=admin_id, archived=True)

    response = await _regenerate(client, strategy_id)

    assert response.status_code == 409
    assert response.json()["detail"]["error"] == "STRATEGY_ARCHIVED"
    assert await _stored_hash(engine, strategy_id) == secret_hash(OLD_SECRET)


async def test_a_user_who_is_not_the_admin_is_not_the_admins_strategys_author(
    client: AsyncClient, engine: AsyncEngine, admin_id: UUID
) -> None:
    """The door is open to every signed-in user (D.4), so a non-admin gets past it
    and is stopped by the scope: the admin's strategy is a 404 to them."""
    strategy_id = await _seed(engine, author=admin_id)

    response = await _regenerate(client, strategy_id, headers=OTHER_HEADERS)

    assert response.status_code == 404
    assert await _stored_hash(engine, strategy_id) == secret_hash(OLD_SECRET)


async def test_regenerating_waits_for_the_strategy_row_lock(
    client: AsyncClient, engine: AsyncEngine, admin_id: UUID
) -> None:
    """The row is read ``FOR UPDATE``: while another transaction holds it (an archive
    in flight), the regenerate waits, and then sees what that transaction left."""
    strategy_id = await _seed(engine, author=admin_id)

    async with engine.connect() as holder:
        await holder.execute(
            text("SELECT id FROM strategies WHERE id = :id FOR UPDATE"), {"id": strategy_id}
        )
        task = asyncio.create_task(_regenerate(client, strategy_id))
        await asyncio.sleep(0.5)
        assert not task.done()

        await holder.execute(
            text("UPDATE strategies SET archived_at = now() WHERE id = :id"), {"id": strategy_id}
        )
        await holder.commit()

    response = await asyncio.wait_for(task, timeout=10)
    assert response.status_code == 409
    assert await _stored_hash(engine, strategy_id) == secret_hash(OLD_SECRET)


# ---------------------------------------------------------------------------
# Nothing logs a secret or a hash
# ---------------------------------------------------------------------------


async def test_no_log_line_carries_a_secret_or_a_hash(
    client: AsyncClient,
    engine: AsyncEngine,
    admin_id: UUID,
    caplog: pytest.LogCaptureFixture,
) -> None:
    created_id = uuid4()
    seeded_id = await _seed(engine, author=admin_id)

    with caplog.at_level(logging.DEBUG):
        created = await client.post(
            "/api/strategies", json=_create_body(created_id), headers=ADMIN_HEADERS
        )
        regenerated = await _regenerate(client, seeded_id)
        refused = await _regenerate(client, uuid4())
        # The flows log nothing on success, so a canary proves the capture is live.
        logging.getLogger("strategy_manager.canary").warning("canary %s", "d3-canary")
    assert (created.status_code, regenerated.status_code, refused.status_code) == (201, 200, 404)

    secrets_and_hashes = [
        created.json()["webhook_secret"],
        regenerated.json()["webhook_secret"],
        OLD_SECRET,
        await _stored_hash(engine, created_id),
        await _stored_hash(engine, seeded_id),
        secret_hash(OLD_SECRET),
    ]
    assert any("d3-canary" in record.getMessage() for record in caplog.records), (
        "the capture saw nothing, so nothing was proven"
    )
    said ="\n".join(
        f"{record.name} {record.getMessage()} {record.args} {record.exc_text}"
        for record in caplog.records
    )
    for value in secrets_and_hashes:
        assert value not in said
